mask.initialization:
% Embedded parameter definitions. This code is stored in the SLX, not an external file.
assert(isscalar(ns) && isfinite(ns) && ns>=1 && ns==fix(ns), 'Series groups must be a positive integer.');
assert(isscalar(np) && isfinite(np) && np>=1 && np==fix(np), 'Parallel cells must be a positive integer.');
assert(isscalar(cell_capacity_Ah) && isfinite(cell_capacity_Ah) && cell_capacity_Ah>0, 'Cell capacity must be positive.');
assert(isscalar(cell_nominal_V) && isfinite(cell_nominal_V) && cell_nominal_V>0, 'Nominal cell voltage must be positive.');
assert(isscalar(cell_resistance_ohm) && isfinite(cell_resistance_ohm) && cell_resistance_ohm>0, 'Cell resistance must be greater than zero.');
assert(numel(cell_voltage_limits_V)==2 && all(isfinite(cell_voltage_limits_V)) && cell_voltage_limits_V(1)>0 && cell_voltage_limits_V(2)>cell_voltage_limits_V(1), 'Enter increasing positive cell voltage limits [min max].');
assert(cell_nominal_V>=cell_voltage_limits_V(1) && cell_nominal_V<=cell_voltage_limits_V(2), 'Nominal voltage must lie within the cell voltage limits.');
assert(numel(current_ratings_C)==2 && all(isfinite(current_ratings_C)) && all(current_ratings_C>=0), 'Enter two nonnegative C-rates [charge discharge].');
assert(numel(soc_levels_pct)==4 && all(isfinite(soc_levels_pct)) && all(diff(soc_levels_pct)>0) && soc_levels_pct(1)>=0 && soc_levels_pct(4)<=100, 'SOC levels must increase: minimum < reserve < taper < maximum, within 0 to 100.');
assert(isscalar(initial_soc_pct) && isfinite(initial_soc_pct) && initial_soc_pct>=soc_levels_pct(1) && initial_soc_pct<=soc_levels_pct(4), 'Initial SOC must lie inside the operating SOC window.');
assert(isscalar(initial_temp_C) && isfinite(initial_temp_C), 'Initial temperature must be a finite scalar.');
assert(numel(charge_temp_limits_C)==4 && all(isfinite(charge_temp_limits_C)) && all(diff(charge_temp_limits_C)>0), 'Enter four increasing charge-temperature limits.');
assert(numel(discharge_temp_limits_C)==4 && all(isfinite(discharge_temp_limits_C)) && all(diff(discharge_temp_limits_C)>0), 'Enter four increasing discharge-temperature limits.');
assert(isscalar(mass_kg) && isfinite(mass_kg) && mass_kg>0 && isscalar(cp_J_kgK) && isfinite(cp_J_kgK) && cp_J_kgK>0, 'Mass and specific heat must be positive.');
assert(isscalar(conductance_W_K) && isfinite(conductance_W_K) && conductance_W_K>=0, 'Ambient conductance must not be negative.');
assert(numel(coulombic_efficiencies)==2 && all(isfinite(coulombic_efficiencies)) && all(coulombic_efficiencies>0) && all(coulombic_efficiencies<=1), 'Coulombic efficiencies must be in (0,1].');
assert(isvector(ocv_soc_pct) && isvector(ocv_cell_V) && numel(ocv_soc_pct)>=2 && numel(ocv_soc_pct)==numel(ocv_cell_V), 'OCV arrays must be equal-length vectors.');
assert(all(isfinite(ocv_soc_pct)) && all(isfinite(ocv_cell_V)) && all(diff(ocv_soc_pct)>0) && ocv_soc_pct(1)==0 && ocv_soc_pct(end)==100, 'OCV SOC breakpoints must increase from 0 to 100.');
assert(all(diff(ocv_cell_V)>=0) && all(ocv_cell_V>=cell_voltage_limits_V(1)) && all(ocv_cell_V<=cell_voltage_limits_V(2)), 'OCV voltages must be nondecreasing and within the cell voltage limits.');
initial_soc=initial_soc_pct/100;
soc_min=soc_levels_pct(1)/100; soc_reserve=soc_levels_pct(2)/100;
soc_taper=soc_levels_pct(3)/100; soc_max=soc_levels_pct(4)/100;
cell_min_V=cell_voltage_limits_V(1); cell_max_V=cell_voltage_limits_V(2);
charge_rate_C=current_ratings_C(1); discharge_rate_C=current_ratings_C(2);
charge_T1_C=charge_temp_limits_C(1); charge_T2_C=charge_temp_limits_C(2);
charge_T3_C=charge_temp_limits_C(3); charge_T4_C=charge_temp_limits_C(4);
discharge_T1_C=discharge_temp_limits_C(1); discharge_T2_C=discharge_temp_limits_C(2);
discharge_T3_C=discharge_temp_limits_C(3); discharge_T4_C=discharge_temp_limits_C(4);
eta_charge=coulombic_efficiencies(1); eta_discharge=coulombic_efficiencies(2);
ocv_soc=ocv_soc_pct/100;
dt_s=1;

% Added exact OCV-integral energy accounting for the comparison.
assert(numel(ocv_soc)==13, 'This version requires13 OCV breakpoints and13 voltages.');
ocv_soc = reshape(ocv_soc,1,[]);
ocv_cell_V = reshape(ocv_cell_V,1,[]);
energy_s = [ocv_soc(ocv_soc<initial_soc) initial_soc];
energy_v = interp1(ocv_soc,ocv_cell_V,energy_s,'linear');
initial_stored_energy_kWh = ns*np*cell_capacity_Ah*trapz(energy_s,energy_v)/1000;
